60.             exc_start() {
61.                 require(!pre.exc_locked);
62.                 update exc_locked = true;
63.                 add exc_pending += Some(0);
64.             }
65.         }
66. 
67.         transition!{
68.             exc_check_count() {
69.                 remove exc_pending -= Some(let r);
70.                 have ref_counts >= [r => 0];
71. 
72.                 add exc_pending += Some(r + 1);
73.             }
74.         }
75. 
76.         transition!{
77.             exc_finish() {
78.                 remove exc_pending -= Some(pre.rc_width);
79.                 add exc_guard += Some(());
80.                 withdraw storage -= Some(let _);
81.             }
82.         }
83. 
84.         transition!{
85.             exc_release(t: T) {
86.                 update exc_locked = false;
87.                 remove exc_guard -= Some(());
88.                 deposit storage += Some(t);
89.             }
90.         }
91. 
92.         transition!{
93.             shared_start(r: int) {
94.                 remove ref_counts -= [r => let rc];
95.                 add ref_counts += [r => rc + 1];
96.                 add shared_pending += {r};
97.             }
98.         }
99. 
100.         transition!{
101.             shared_finish(r: int) {
102.                 require(!pre.exc_locked);
103.                 remove shared_pending -= {r};
104. 
105.                 birds_eye let t = pre.storage->0;
106.                 add shared_guard += {(r, t)};
107.             }
108.         }
109. 
110.         transition!{
111.             shared_release(val: (int, T)) {
112.                 remove shared_guard -= {val};
113. 
114.                 let r = val.0;
115.                 remove ref_counts -= [r => let rc];
116.                 add ref_counts += [r => rc - 1];
117. 
118.                 assert(rc > 0) by {
119.                     assert(0 <= r < pre.rc_width);
120.                     assert(pre.shared_guard.count(val) > 0);
121.                     assert(Self::filter_r(pre.shared_guard, r).count(val) > 0);
122.                     assert(Self::filter_r(pre.shared_guard, r).len() > 0);
123.                     assert(pre.ref_counts.index(r) > 0);
124.                 };
125.             }
126.         }
127. 
128.         property!{
129.             do_guard(val: (int, T)) {
130.                 have shared_guard >= {val};
131.                 guard storage >= Some(val.1);
132.             }
133.         }
