136.         #[invariant]
137.         pub fn ref_counts_domain(&self) -> bool {
138.             &&& 0 < self.rc_width
139.             &&& forall |i: int| 0 <= i < self.rc_width <==> self.ref_counts.dom().contains(i)
140.         }
141. 
142.         #[invariant]
143.         pub fn exc_inv(&self) -> bool {
144.             &&& self.exc_locked <==> (self.exc_pending is Some || self.exc_guard is Some)
145.             &&& self.storage is Some <==> self.exc_guard is None
146.             &&& if let Option::Some(cur_r) = self.exc_pending {
147.                 &&& 0 <= cur_r <= self.rc_width
148.                 &&& self.exc_guard is None
149.                 &&& forall |x| self.shared_guard.count(x) > 0 ==> !(0 <= x.0 < cur_r)
150.             } else {
151.                 true
152.             }
153.         }
154. 
155.         #[invariant]
156.         pub fn shared_pending_in_range(&self) -> bool {
157.             forall |r| self.shared_pending.count(r) > 0 ==> (0 <= r < self.rc_width)
158.         }
159. 
160.         #[invariant]
161.         pub fn shared_guard_in_range(&self) -> bool {
162.             forall |x| self.shared_guard.count(x) > 0 ==> (0 <= x.0 < self.rc_width)
163.         }
